import React from 'react';
import { X, Twitter, MessageCircle, ExternalLink, TrendingUp, Shield, BarChart3, User, Activity, AlertTriangle } from 'lucide-react';

const TokenDetails = ({ token, onClose }) => {
  if (!token) return null;

  const formatNumber = (num) => {
    if (!num || isNaN(num)) return 'N/A';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    if (num >= 1e3) return (num / 1e3).toFixed(2) + 'K';
    return num.toFixed(2);
  };

  const formatPercentage = (num) => {
    if (!num || isNaN(num)) return 'N/A';
    return (num >= 0 ? '+' : '') + num.toFixed(2) + '%';
  };

  const formatPrice = (price) => {
    if (!price || isNaN(price)) return 'N/A';
    if (price < 0.000001) return price.toExponential(4);
    if (price < 0.01) return price.toFixed(8);
    if (price < 1) return price.toFixed(6);
    if (price < 100) return price.toFixed(4);
    return price.toFixed(2);
  };

  const getScoreColor = (score) => {
    if (score >= 7) return 'text-green-400';
    if (score >= 4) return 'text-yellow-400';
    return 'text-red-400';
  };

  const getScoreLabel = (score) => {
    if (score >= 7) return 'Good';
    if (score >= 4) return 'Average';
    return 'Poor';
  };

  const getCommunityLabel = (score) => {
    if (score >= 7) return 'Strong';
    if (score >= 4) return 'Medium';
    return 'Weak';
  };

  const getLiquidityStatus = (liquidity, marketCap) => {
    if (!liquidity || !marketCap) return { icon: '❓', color: 'text-gray-400' };
    const ratio = (liquidity / marketCap) * 100;
    if (ratio > 20) return { icon: '🟢', color: 'text-green-400' };
    if (ratio < 10) return { icon: '🔴', color: 'text-red-400' };
    return { icon: '🟡', color: 'text-yellow-400' };
  };

  const getOrganicLabel = (score) => {
    if (score >= 70) return 'High';
    if (score >= 40) return 'Medium';
    return 'Low';
  };

  const getCommunityHealthLabel = (score) => {
    if (score >= 7) return 'High';
    if (score >= 4) return 'Medium';
    return 'Low';
  };

  const getRiskLevel = (score) => {
    if (score >= 7) return { level: 'Low', icon: '🟢', color: 'text-green-400' };
    if (score >= 4) return { level: 'Medium', icon: '🟡', color: 'text-yellow-400' };
    return { level: 'High', icon: '🔴', color: 'text-red-400' };
  };

  const getSentimentEmoji = (score) => {
    if (score >= 7) return '😃';
    if (score >= 4) return '😐';
    return '😡';
  };

  const liquidityStatus = getLiquidityStatus(token.jupiterData?.liquidity, token.jupiterData?.marketCap);
  const riskLevel = getRiskLevel(token.score || token.overallScore || 0);
  const sentimentEmoji = getSentimentEmoji(token.sentimentScore || 5);

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4">
      <div className="bg-dark-bg border border-gray-700 rounded-xl max-w-6xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-dark-bg border-b border-gray-700 p-6 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            {token.image && (
              <img src={token.image} alt={token.name} className="w-16 h-16 rounded-full border-2 border-blue-500" />
            )}
            <div>
              <h2 className="text-3xl font-bold text-white">{token.symbol} – {token.name}</h2>
              <p className="text-gray-400 text-lg">🪄 Token Scorecard</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        <div className="p-6 space-y-8">
          {/* ⭐ Section 1 – Overall Score, Mentions, Community */}
          <div className="bg-gradient-to-r from-blue-900/20 to-purple-900/20 rounded-xl p-6 border border-blue-500/30">
            <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
              ⭐ Performance Overview
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {/* 📊 Overall Score */}
              <div className="text-center">
                <div className={`text-6xl font-bold mb-3 ${getScoreColor(token.score || token.overallScore || 0)}`}>
                  {token.score || token.overallScore || 0}
                </div>
                <div className="text-gray-400 text-lg mb-2">📊 Overall Score</div>
                <div className={`text-xl font-semibold ${getScoreColor(token.score || token.overallScore || 0)}`}>
                  {getScoreLabel(token.score || token.overallScore || 0)}
                </div>
                <div className="text-xs text-gray-500 mt-2">0-10 scale</div>
              </div>

              {/* 💬 Mentions (24h) */}
              <div className="text-center">
                <div className="text-6xl font-bold mb-3 text-blue-400">
                  {token.mentions || token.uniqueMentions || 0}
                </div>
                <div className="text-gray-400 text-lg mb-2">💬 Mentions (24h)</div>
                <div className="flex items-center justify-center space-x-2">
                  <span className="text-2xl">
                    {token.mentionsTrend > 0 ? '📈' : token.mentionsTrend < 0 ? '📉' : '➡️'}
                  </span>
                  <span className={`text-lg font-semibold ${token.mentionsTrend > 0 ? 'text-green-400' : token.mentionsTrend < 0 ? 'text-red-400' : 'text-gray-400'}`}>
                    {token.mentionsTrend > 0 ? '+' : ''}{token.mentionsTrend || 0}% vs yesterday
                  </span>
                </div>
              </div>

              {/* 👥 Community Score */}
              <div className="text-center">
                <div className="text-6xl font-bold mb-3 text-green-400">
                  {token.communityScore || token.communityHealth || 0}
                </div>
                <div className="text-gray-400 text-lg mb-2">👥 Community Score</div>
                <div className="text-xl font-semibold text-green-400">
                  {getCommunityLabel(token.communityScore || token.communityHealth || 0)}
                </div>
                <div className="text-xs text-gray-500 mt-2">0-10 rating</div>
              </div>
            </div>
          </div>

          {/* 🔍 Section 2 – Insights (ex-Jupiter API Data) */}
          {token.jupiterData && (
            <div className="bg-gradient-to-r from-purple-900/20 to-pink-900/20 rounded-xl p-6 border border-purple-500/30">
              <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
                🔍 Insights
                <span className="ml-3 text-sm text-purple-400 bg-purple-400/10 px-3 py-1 rounded-full">
                  Live Data
                </span>
              </h3>

              {/* Basic Info Grid */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🪙 Total Supply</div>
                  <div className="text-white font-semibold text-lg">
                    {token.jupiterData.totalSupply ? formatNumber(Number(token.jupiterData.totalSupply)) : 'N/A'}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">👛 Holder Count</div>
                  <div className="text-white font-semibold text-lg">
                    {token.jupiterData.holderCount ? formatNumber(token.jupiterData.holderCount) : 'N/A'}
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    {token.jupiterData.holderChange24h > 0 ? '📈' : token.jupiterData.holderChange24h < 0 ? '📉' : '➡️'} 24h
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">📅 Creation Date</div>
                  <div className="text-white font-semibold text-sm">
                    {token.jupiterData.creationTime ? new Date(token.jupiterData.creationTime).toLocaleDateString() : 'N/A'}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🚀 Launchpad</div>
                  <div className="text-white font-semibold text-sm">
                    {token.jupiterData.launchpad || 'N/A'}
                  </div>
                </div>
              </div>

              {/* Market Data */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">💰 Market Cap</div>
                  <div className="text-white font-semibold text-lg">
                    ${formatNumber(token.jupiterData.marketCap)}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">💎 FDV</div>
                  <div className="text-white font-semibold text-lg">
                    {token.jupiterData.fdv ? `$${formatNumber(token.jupiterData.fdv)}` : 'N/A'}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">💲 Price (USD)</div>
                  <div className="text-white font-semibold text-lg">
                    ${formatPrice(token.jupiterData.price)}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">💧 Liquidity</div>
                  <div className="text-white font-semibold text-lg">
                    ${formatNumber(token.jupiterData.liquidity)}
                  </div>
                  <div className={`text-sm mt-1 ${liquidityStatus.color}`}>
                    {liquidityStatus.icon} {token.jupiterData.liquidity && token.jupiterData.marketCap ? 
                      ((token.jupiterData.liquidity / token.jupiterData.marketCap) * 100).toFixed(1) + '% of MC' : 'N/A'}
                  </div>
                </div>
              </div>

              {/* Organic Metrics */}
              {token.jupiterData.organicMetrics && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                    <div className="text-gray-400 text-sm mb-2">🧭 Organic Score</div>
                    <div className="text-white font-semibold text-2xl">
                      {token.jupiterData.organicMetrics.organicScore?.toFixed(1) || 'N/A'}/100
                    </div>
                    <div className="text-sm text-gray-400 mt-1">
                      {getOrganicLabel(token.jupiterData.organicMetrics.organicScore)}
                    </div>
                  </div>
                  <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                    <div className="text-gray-400 text-sm mb-2">🌱 Community Health</div>
                    <div className="text-white font-semibold text-2xl">
                      {token.jupiterData.organicMetrics.communityHealth?.toFixed(1) || 'N/A'}/10
                    </div>
                    <div className="text-sm text-gray-400 mt-1">
                      {getCommunityHealthLabel(token.jupiterData.organicMetrics.communityHealth)}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* 🛡️ Section 3 – Audit Information */}
          {token.jupiterData?.auditInfo && (
            <div className="bg-gradient-to-r from-yellow-900/20 to-orange-900/20 rounded-xl p-6 border border-yellow-500/30">
              <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
                🛡️ Audit Information
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🔒 Mint Authority</div>
                  <div className={`font-semibold text-lg ${token.jupiterData.auditInfo.mintAuthorityDisabled ? 'text-green-400' : 'text-red-400'}`}>
                    {token.jupiterData.auditInfo.mintAuthorityDisabled ? '🟢 Disabled' : '🔴 Enabled'}
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    {token.jupiterData.auditInfo.mintAuthorityDisabled ? 'Safe' : 'Unsafe'}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🔑 Freeze Authority</div>
                  <div className={`font-semibold text-lg ${token.jupiterData.auditInfo.freezeAuthorityDisabled ? 'text-green-400' : 'text-red-400'}`}>
                    {token.jupiterData.auditInfo.freezeAuthorityDisabled ? '🟢 Disabled' : '🔴 Enabled'}
                  </div>
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🐋 Top Holders %</div>
                  <div className="text-white font-semibold text-lg">
                    {token.jupiterData.auditInfo.topHoldersPercentage?.toFixed(1) || 'N/A'}%
                  </div>
                  {token.jupiterData.auditInfo.topHoldersPercentage > 30 && (
                    <div className="text-yellow-400 text-sm mt-1">⚠️ High concentration</div>
                  )}
                </div>
                <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                  <div className="text-gray-400 text-sm mb-2">🧊 Dev Balance %</div>
                  <div className={`font-semibold text-lg ${token.jupiterData.auditInfo.devBalancePercentage === 0 ? 'text-green-400' : 'text-red-400'}`}>
                    {token.jupiterData.auditInfo.devBalancePercentage === 0 ? '🟢 CTO' : `🔴 ${token.jupiterData.auditInfo.devBalancePercentage?.toFixed(2) || 'N/A'}%`}
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    {token.jupiterData.auditInfo.devBalancePercentage === 0 ? 'Community Takeover' : 'Official'}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* 📈 Section 4 – Detailed Stats Timeline */}
          {token.jupiterData?.timeStats && (
            <div className="bg-gradient-to-r from-green-900/20 to-emerald-900/20 rounded-xl p-6 border border-green-500/30">
              <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
                📈 Detailed Stats Timeline
                <span className="ml-3 text-sm text-green-400 bg-green-400/10 px-3 py-1 rounded-full">
                  Live Data
                </span>
              </h3>

              {/* 1 Hour Stats */}
              {token.jupiterData.timeStats.stats1h && (
                <div className="mb-8">
                  <h4 className="text-xl font-semibold mb-4 text-white">⏰ 1 Hour Stats</h4>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📈 Price Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats1h.priceChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats1h.priceChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">👛 Holder Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats1h.holderChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats1h.holderChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">💧 Liquidity Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats1h.liquidityChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats1h.liquidityChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🔄 Buy/Sell Volumes</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats1h.buyVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats1h.sellVolume || 0)}
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🧑‍🤝‍🧑 Unique Traders</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats1h.numTraders || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📉 Net Buyers</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats1h.numNetBuyers || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🌱 Organic Volume</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats1h.buyOrganicVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats1h.sellOrganicVolume || 0)}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* 6 Hour Stats */}
              {token.jupiterData.timeStats.stats6h && (
                <div className="mb-8">
                  <h4 className="text-xl font-semibold mb-4 text-white">⏰ 6 Hour Stats</h4>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📈 Price Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats6h.priceChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats6h.priceChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">👛 Holder Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats6h.holderChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats6h.holderChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">💧 Liquidity Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats6h.liquidityChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats6h.liquidityChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🔄 Buy/Sell Volumes</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats6h.buyVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats6h.sellVolume || 0)}
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🧑‍🤝‍🧑 Unique Traders</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats6h.numTraders || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📉 Net Buyers</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats6h.numNetBuyers || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🌱 Organic Volume</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats6h.buyOrganicVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats6h.sellOrganicVolume || 0)}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* 24 Hour Stats */}
              {token.jupiterData.timeStats.stats24h && (
                <div className="mb-4">
                  <h4 className="text-xl font-semibold mb-4 text-white">⏰ 24 Hour Stats</h4>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📈 Price Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats24h.priceChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats24h.priceChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">👛 Holder Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats24h.holderChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats24h.holderChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">💧 Liquidity Change %</div>
                      <div className={`font-semibold text-lg ${token.jupiterData.timeStats.stats24h.liquidityChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {formatPercentage(token.jupiterData.timeStats.stats24h.liquidityChange)}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🔄 Buy/Sell Volumes</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats24h.buyVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats24h.sellVolume || 0)}
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🧑‍🤝‍🧑 Unique Traders</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats24h.numTraders || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">📉 Net Buyers</div>
                      <div className="text-white font-semibold text-lg">
                        {token.jupiterData.timeStats.stats24h.numNetBuyers || 'N/A'}
                      </div>
                    </div>
                    <div className="bg-dark-bg p-4 rounded-lg border border-gray-700">
                      <div className="text-gray-400 text-sm mb-2">🌱 Organic Volume</div>
                      <div className="text-white font-semibold text-sm">
                        B: {formatNumber(token.jupiterData.timeStats.stats24h.buyOrganicVolume || 0)}
                      </div>
                      <div className="text-white font-semibold text-sm">
                        S: {formatNumber(token.jupiterData.timeStats.stats24h.sellOrganicVolume || 0)}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* 🪪 Section 5 – Profile Information */}
          <div className="bg-gradient-to-r from-indigo-900/20 to-blue-900/20 rounded-xl p-6 border border-indigo-500/30">
            <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
              🪪 Profile Information
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">🏷️ Official Profile:</span>
                  <span className={`px-4 py-2 rounded-full text-lg font-medium ${
                    token.twitterHandle ? 'bg-green-400/10 text-green-400' : 'bg-red-400/10 text-red-400'
                  }`}>
                    {token.twitterHandle ? '✅ Found' : '❌ Not Found'}
                  </span>
                </div>
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">🌍 Community Type:</span>
                  <span className={`px-4 py-2 rounded-full text-lg font-medium ${
                    token.jupiterData?.auditInfo?.devBalancePercentage === 0 ? 'bg-green-400/10 text-green-400' : 'bg-blue-400/10 text-blue-400'
                  }`}>
                    {token.jupiterData?.auditInfo?.devBalancePercentage === 0 ? '🟢 CTO' : '🔵 Official'}
                  </span>
                </div>
                {token.twitterHandle && (
                  <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                    <span className="text-gray-400 text-lg">🐦 Twitter Followers:</span>
                    <span className="text-white font-semibold text-lg">
                      👥 {token.twitterFollowers ? formatNumber(token.twitterFollowers) : 'N/A'}
                    </span>
                  </div>
                )}
              </div>

              {/* Social Links */}
              <div className="space-y-4">
                <h4 className="text-xl font-semibold text-white mb-4">🔗 Social Links</h4>
                <div className="space-y-3">
                  {token.twitterHandle && (
                    <a
                      href={`https://twitter.com/${token.twitterHandle}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center space-x-3 bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-lg transition-colors"
                    >
                      <Twitter className="w-5 h-5" />
                      <span className="text-lg">@{token.twitterHandle}</span>
                    </a>
                  )}
                  {token.jupiterData?.socials?.telegram && (
                    <a
                      href={token.jupiterData.socials.telegram}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center space-x-3 bg-blue-500 hover:bg-blue-600 text-white p-4 rounded-lg transition-colors"
                    >
                      <MessageCircle className="w-5 h-5" />
                      <span className="text-lg">Telegram</span>
                    </a>
                  )}
                  {token.jupiterData?.socials?.website && (
                    <a
                      href={token.jupiterData.socials.website}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center space-x-3 bg-gray-600 hover:bg-gray-700 text-white p-4 rounded-lg transition-colors"
                    >
                      <ExternalLink className="w-5 h-5" />
                      <span className="text-lg">Website</span>
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* 🐦 Section 6 – Social Activity */}
          {token.recentPosts && token.recentPosts.length > 0 && (
            <div className="bg-gradient-to-r from-blue-900/20 to-cyan-900/20 rounded-xl p-6 border border-blue-500/30">
              <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
                🐦 Social Activity
              </h3>
              <div className="space-y-4">
                {token.recentPosts.map((post, index) => (
                  <div key={index} className="bg-dark-bg p-6 rounded-lg border border-gray-700">
                    <div className="flex items-start space-x-4">
                      <div className="flex-shrink-0">
                        <div className="w-12 h-12 bg-blue-500 rounded-full flex items-center justify-center">
                          <Twitter className="w-6 h-6 text-white" />
                        </div>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center space-x-3 mb-3">
                          <span className="text-white font-medium text-lg">@{token.twitterHandle || 'User'}</span>
                          <span className="text-gray-400 text-sm">
                            {post.timestamp ? new Date(post.timestamp).toLocaleDateString() : 'Recent'}
                          </span>
                        </div>
                        <p className="text-gray-300 text-base leading-relaxed mb-4">
                          {post.content || post.text || 'Tweet content not available'}
                        </p>
                        <div className="flex items-center justify-between">
                          <div className="flex items-center space-x-6 text-sm">
                            <div className="flex items-center space-x-2 text-red-400">
                              <span>❤️</span>
                              <span>{post.likes || 0}</span>
                            </div>
                            <div className="flex items-center space-x-2 text-green-400">
                              <span>🔁</span>
                              <span>{post.retweets || 0}</span>
                            </div>
                            <div className="flex items-center space-x-2 text-blue-400">
                              <span>💬</span>
                              <span>{post.replies || 0}</span>
                            </div>
                          </div>
                          {post.url && (
                            <a
                              href={post.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-block text-blue-400 hover:text-blue-300 text-sm"
                            >
                              View Tweet →
                            </a>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* 📊 Section 7 – Metrics Breakdown */}
          <div className="bg-gradient-to-r from-purple-900/20 to-pink-900/20 rounded-xl p-6 border border-purple-500/30">
            <h3 className="text-2xl font-bold mb-6 text-white flex items-center">
              📊 Metrics Breakdown
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">😊 Sentiment Score:</span>
                  <span className="text-white font-semibold text-lg">
                    {sentimentEmoji} {(token.sentimentScore || 5).toFixed(1)}/10
                  </span>
                </div>
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">📣 Engagement Rate:</span>
                  <span className="text-white font-semibold text-lg">
                    {((token.engagementRate || 0.05) * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">🧑‍🤝‍🧑 Unique Mentions:</span>
                  <span className="text-white font-semibold text-lg">
                    {(token.uniqueMentions || Math.floor((token.mentions || 0) * 0.7)).toLocaleString()}
                  </span>
                </div>
                <div className="flex items-center justify-between p-4 bg-dark-bg rounded-lg border border-gray-700">
                  <span className="text-gray-400 text-lg">⚠️ Risk Level:</span>
                  <span className={`px-4 py-2 rounded-full text-lg font-medium ${riskLevel.color}`}>
                    {riskLevel.icon} {riskLevel.level}
                  </span>
                </div>
              </div>

              {/* Enhanced Score Breakdown */}
              {token.enhancedScore && (
                <div>
                  <h4 className="text-xl font-semibold text-white mb-4">🎯 Enhanced Score Components</h4>
                  <div className="space-y-3">
                    {Object.entries(token.enhancedScore.components || {}).map(([key, value]) => (
                      <div key={key} className="flex items-center justify-between p-3 bg-dark-bg rounded-lg border border-gray-700">
                        <span className="text-gray-400 capitalize">
                          {key.replace(/([A-Z])/g, ' $1').trim()}
                        </span>
                        <span className="text-white font-semibold">
                          {typeof value === 'number' ? value.toFixed(2) : value}
                        </span>
                      </div>
                    ))}
                    <div className="flex items-center justify-between p-3 bg-green-600/20 rounded-lg border border-green-500/30">
                      <span className="text-gray-300">🚀 Fuel Bonus</span>
                      <span className="text-green-400 font-semibold">
                        +{token.enhancedScore.fuelBonus || 0}
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {token.enhancedScore?.calculationTime && (
              <div className="mt-6 pt-4 border-t border-gray-600">
                <div className="text-center text-gray-400 text-sm">
                  Last calculated: {new Date(token.enhancedScore.calculationTime).toLocaleString()}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TokenDetails;
